$_document.click(function (e){	
	var container = $(".menu-button");
	if (!container.is(e.target) && container.has(e.target).length === 0 ){
		$(".circular-menu").removeClass("open");
	}
	if (!$(".circle").is(e.target) && $(".circle").has(e.target).length === 0 ){
		$(".menu_plus").removeClass("open");
	}
});
function open_news(_this, e){
	e.preventDefault();
	var news_id = $(_this).attr('news_id'),
		project_id = $(_this).attr('project_id'),
		block_id = $(_this).attr('block_id'),
		gid = $(_this).attr('gid'),
		action = $(_this).attr('action');
	$Core.util.toggleIndicatior(1);
	$.post('/index.php?mod=home&act=open_news', {
		'news_id' : news_id,
		'project_id' : project_id,
		'block_id' : block_id,
		'action' : action,
		'gid' 	: gid
	}, function(respJson){
		$Core.util.toggleIndicatior(0);
		$Core.popup.open('auto','auto',respJson.html,respJson.uid);
		if(action=='_detail'){
			$Core.news.load_comments(news_id, 'News', {'action' : 'reload'});
		}
		$('#'+respJson.uid).on('shown.bs.modal', function(){
			var _modal = $(this);
			$('#gallery-grid-'+news_id,_modal).imagesGrid({
				cells:4,
				images: respJson.list_images,
				align: true
			});
			if($(".select_tag").length){
				$(".select_tag").each((_i, _elem) => {
					var list_tags = $(_elem).val();
					console.log(list_tags);
					$.post('/index.php?mod=home&sub=news&act=load_tags', {"list_tags":list_tags}, function(respJson){
						$(_elem).html(respJson.html);
						$(_elem).select2();
					}, 'json');
				});
			}
			if($(".attachments").length > 0) {
				$('#attachments_'+respJson.uid).MultiFile({
					list: '#MultiFile-preview_'+respJson.uid
				});
			}
		});
	}, 'json');
	return false;
}
function open_gratitude(_this, e){
	e.preventDefault();
	var news_id = $(_this).attr('news_id'),
		gid = $(_this).attr('gid'),
		action = $(_this).attr('action');
	$Core.util.toggleIndicatior(1);
	$_data = {
		'news_id' 	: news_id,
		'action' 	: action,
		'gid' 		: gid
	};
	$.post('/index.php?mod=home&act=open_gratitude', $_data, function(respJson){
		$Core.util.toggleIndicatior(0);
		$Core.popup.open('auto','auto',respJson.html,respJson.uid);
		if(action=='_detail'){
			$Core.news.load_comments(news_id, 'News', {'action' : 'reload'});
		}
		$('#'+respJson.uid).on('shown.bs.modal', function(){
			var _modal = $(this);
			$('#gallery-grid-'+news_id,_modal).imagesGrid({
				cells:4,
				images: respJson.list_images,
				align: true
			});
		});
		$(_this).removeClass("bg-grayter").addClass("bg-white");
	}, 'json');
	return false;
}
