$Core.today = {	
	open_stock_today: function(_this, e){
		e.preventDefault();
		var action = $(_this).data("action");
		$Core.util.toggleIndicatior(1);
		$.post(PCMS_URL+'/index.php?mod=ajax&sub=helper&act=open_stock_today', {
			'action' : action
		}, function(respJson){
			$Core.util.toggleIndicatior(0);
			$Core.popup.open('auto','auto',respJson.html,respJson.uid);
		},'json');
		return false;
	},
	edit_stock_today: function(_this, e){
		e.preventDefault();
		var action = $(_this).data("action"),
			today_id = $(_this).data("today_id");
		if(action == "_dupplicate" && !confirm("Bạn chắc chắn muốn nhân bản căn nổi bật này")){
			return false;
		}
		$Core.util.toggleIndicatior(1);
		$.post(PCMS_URL+'/index.php?mod=ajax&sub=helper&act=edit_stock_today', {
			'action' : action,
			'today_id' : today_id,
		}, function(respJson){
			$Core.util.toggleIndicatior(0);
			$Core.popup.open('auto','auto',respJson.html,respJson.uid);
			$('#'+uid).on('shown.bs.modal', function (e) {
				if ($(".modal-backdrop").length > 1) {				
					$(".modal-backdrop").not(':last').remove();
				}
			});
			if(action == "_dupplicate"){
				$Core.today.list({});
			}
		},'json');
		return false;
	},
	delete_today: function(_this, e){
		e.preventDefault();
		var today_id = $(_this).data("today_id");
		if(confirm("Bạn chắc chắn muốn xoá căn nổi bật này")){
			$Core.util.toggleIndicatior(1);
			$.post(PCMS_URL+'/index.php?mod=ajax&sub=helper&act=delete_today', {
				'today_id' : today_id,
			}, function(respJson){
				$Core.util.toggleIndicatior(0);
				if(respJson.result){
					alertify.success("Xoá thành công!");
					$("#pager").html("");	
					$Core.today.list({});
				}else{
					alertify.success("Xoá thất bại!");
					window.location.reload();
				}				
			},'json');
		}
		return false;
	},
	save_stock_today: function(_this, e){
		e.preventDefault();
		var _validated = 0,
			today_id = $(_this).attr('today_id'),
			_form = $(_this).closest("form");
		$("select.required,input.required",_form).each(function(_i, _elm){
			if($Core.util.isEmpty($(_elm).val())){
				_validated ++;
				$(_elm).focus();
				return false;
			}
		});
		if(_validated == 0){
			$Core.util.toggleIndicatior(1);
			_form.ajaxSubmit({
				type : 'POST',
				url :PCMS_URL+'/index.php?mod=ajax&sub=helper&act=save_stock_today',
				data: {'today_id':today_id},
				success : function(html){
					$Core.util.toggleIndicatior(0);
					if(html.indexOf('_success') >= 0){
						alertify.success("Thành công!");	
						$(_this).closest(".modal").modal("hide");
						if(MOD=="home" && ACT == "today") {
							$Core.today.list({});
						}
					}
				}
			});
		}
		return false;
	},
	check_stock_code: function(_this, e){
		var stock_code = $(_this).val();
		if(!$Core.util.isEmpty(stock_code)){
			$Core.util.toggleIndicatior(1);
			$.post(PCMS_URL+'/index.php?mod=ajax&sub=helper&act=check_stock_code', {
				'stock_code' : stock_code
			}, function(respJson){
				$Core.util.toggleIndicatior(0);
				if(respJson.msg.indexOf('_invalid') >= 0){
					$('button[type=submit]').attr('disabled','disabled');
					$(_this).addClass('is-invalid').removeClass('is-valid');
					$Core.swal.error('Thông báo', "Mã căn "+stock_code+" không tồn tại");
				} else {
					$('input[name=stock_id]').val(respJson.stock_id);
					$(_this).addClass('is-valid').removeClass('is-invalid');
					$('button[type=submit]').removeAttr('disabled');					
					$('.bs-webui-popover').webuiPopover('hideAll');
				}
			}, 'json');
		} else {
			$(_this).removeClass('is-valid');
			$(_this).removeClass('is-invalid');
			$('button[type=submit]').attr('disabled','disabled');
		}
	},
	do_upload: function(_this, e){
		console.log('saaaass');
		var total_images = 0,
			_form = $(_this).closest("form"),
			formData = new FormData(),
			files = $(_this).prop('files');
		if($('input[name=total_images]').length){
			total_images = $('input[name=total_images]',_form).val();
		}
		if(parseInt(total_images,10) >= 20){
			$Core.messager.alert("Thông báo", "Bạn không được sử dụng quá 20 hình ảnh");
			return false;
		}
		if (files && files.length) {
			for (var i = 0; i < files.length; i++) {
				formData.append('images[]', files[i]);
			}
		}
		formData.append('total_images',total_images);
		$Core.util.toggleIndicatior(1);
		$.ajax({
			url: PCMS_URL+"/index.php?mod=ajax&sub=helper&act=upload_image",
			method: "POST",
			data: formData,
			contentType: false,
			cache: false,
			processData: false,
			dataType : 'json',
			success: function (respJson) {
				$Core.util.toggleIndicatior(0);
				if(respJson.msg.indexOf('_success') >= 0){
					$('input[name=total_images]',_form).val(respJson.total_images);
					if($('.imageList .item',_form).length){
						$('.imageList .item:last',_form).after(respJson.html);
					} else {
						$('.imageList',_form).html(respJson.html);
					}
					$(".delete_all",_form).show();
				}
			}
		});
	},	
	delete_image: function(_this, e){
		e.preventDefault();
		var _form = $(_this).closest("form"),
			type = $(_this).data("type"),
			total_images = $('input[name=total_images]',_form).val(),
			today_id = $('input[name=today_id]',_form).val();
		if(type == "all"){
			var msg = "Bạn chắc chắn muốn xóa tất cả hình ảnh";
		}else{
			var msg = "Bạn chắc chắn muốn xóa hình ảnh này";
		}
		$Core.messager.confirm('Message', msg, function(){
			$.post(PCMS_URL+"/index.php?mod=ajax&sub=helper&act=delete_image", {
				'src' : $(_this).attr('src'),"today_id":today_id,"type":type
			}, function(html){
				if(type == "all"){
					$(".imageList",_form).html(html);
					$('input[name=total_images]',_form).val(0);
					$(".delete_all",_form).hide();
				}else{
					$(_this).closest('.item').remove();
					$('input[name=total_images]',_form).val(parseInt(total_images,10) - 1);
					if(html != ""){
						$(".imageList",_form).html(html);
						$(".delete_all",_form).hide();
					}
				}
			});
		});
		return false;
	},
	list: function (options, hide_loading = false){
		var $_adata = options || {};
		if($('.search_field').length){
			$('.search_field').each((_i, _elem) => {
				var field = $(_elem).data('field');
				$_adata[field] = $(_elem).val();
			});
		}
		if(hide_loading==false){
			$Core.util.toggleIndicatior(1);
		}
		$.post('/index.php?mod=ajax&sub=helper&act=load_today', $_adata, function(respJson){
			$Core.util.toggleIndicatior(0);
			$('.holder_today').html(respJson.html);
			$('.total_record').html("Tổng số: "+respJson.total_record+" căn hộ");
			if(parseInt(respJson.total_page) > 1){
				$('#pager').pagination({
					listStyle:"pagination justify-content-center",
					items: respJson.total_record,
					itemsOnPage: respJson.per_page,
					currentPage: respJson.current_page, 
					cssStyle: 'light-theme',
					prevText : '<i class="tf-icon bx bx-chevrons-left"></i>',
					nextText : '<i class="tf-icon bx bx-chevrons-right"></i>',
					onPageClick : function(pageNumber){
						$Core.today.list($.extend(options, {'page':pageNumber}), false);
					}
				});
			}
		},'json');
	},
	status: function(_this, e){
		var today_id = $(_this).attr('today_id'),
			field = $(_this).data('field'),
			status = $(_this).is(':checked') ? 1: 0;
		$Core.util.toggleIndicatior(1);
		$.post(PCMS_URL+'/index.php?mod=ajax&sub=helper&act=status_today', {
			'today_id' : today_id,
			'field' : field,
			'status' : status
		}, function(respJson){
			$Core.util.toggleIndicatior(0);
			if(respJson.result){
				$Core.alert.success('Thành công!');
			} else {
				$Core.alert.error('Thất bại!');
			}
			$Core.today.list({});
		},"json");
	},
}
